PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE content_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  section_key TEXT NOT NULL,
  period INTEGER NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  content_json TEXT NOT NULL DEFAULT '{}',
  result_text TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','win','lose')),
  sort_order INTEGER NOT NULL DEFAULT 0,
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, lottery_type INTEGER NOT NULL DEFAULT 5);
CREATE TABLE masters (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL UNIQUE,
  avatar TEXT NOT NULL DEFAULT '',
  rank_no INTEGER NOT NULL DEFAULT 99,
  specialty TEXT NOT NULL DEFAULT '',
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE master_posts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  master_id INTEGER NOT NULL,
  period INTEGER NOT NULL,
  content_json TEXT NOT NULL DEFAULT '{}',
  result_text TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','win','lose')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(master_id, period),
  FOREIGN KEY(master_id) REFERENCES masters(id) ON DELETE CASCADE
);
CREATE TABLE ads (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  position_key TEXT NOT NULL UNIQUE,
  image_url TEXT NOT NULL DEFAULT '',
  link_url TEXT NOT NULL DEFAULT '',
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, display_mode TEXT NOT NULL DEFAULT 'always', delay_seconds INTEGER NOT NULL DEFAULT 1, start_at TEXT, end_at TEXT);
CREATE TABLE site_settings (
  setting_key TEXT PRIMARY KEY,
  setting_value TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE analytics_visitors (
  ip_address TEXT PRIMARY KEY,
  country TEXT NOT NULL DEFAULT '',
  region_name TEXT NOT NULL DEFAULT '',
  city TEXT NOT NULL DEFAULT '',
  views INTEGER NOT NULL DEFAULT 1,
  first_seen TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_seen TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE analytics_daily (
  visit_date TEXT PRIMARY KEY,
  views INTEGER NOT NULL DEFAULT 0,
  unique_visitors INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE analytics_uniques (
  visit_date TEXT NOT NULL,
  ip_address TEXT NOT NULL,
  PRIMARY KEY(visit_date, ip_address)
);
CREATE TABLE automation_runs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  task_key TEXT NOT NULL DEFAULT 'result_check',
  period INTEGER,
  status TEXT NOT NULL DEFAULT 'running',
  checked_count INTEGER NOT NULL DEFAULT 0,
  updated_count INTEGER NOT NULL DEFAULT 0,
  message TEXT NOT NULL DEFAULT '',
  started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  finished_at TEXT
);
CREATE TABLE recommended_sites (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,site_url TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ad_stats (position_key TEXT PRIMARY KEY,impressions INTEGER NOT NULL DEFAULT 0,clicks INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE text_ads (id INTEGER PRIMARY KEY AUTOINCREMENT,ad_text TEXT NOT NULL,link_url TEXT NOT NULL DEFAULT '',text_color TEXT NOT NULL DEFAULT '#f2cf68',sort_order INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE text_ad_domains (id INTEGER PRIMARY KEY AUTOINCREMENT,domain_url TEXT NOT NULL UNIQUE,sort_order INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE text_ad_imports (import_key TEXT PRIMARY KEY,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_content_section_period ON content_items(section_key, period DESC, sort_order, id);
CREATE INDEX idx_masters_rank ON masters(enabled, rank_no, id);
CREATE INDEX idx_analytics_visitors_last ON analytics_visitors(last_seen DESC);
CREATE INDEX idx_automation_runs_started ON automation_runs(started_at DESC);
CREATE INDEX idx_recommended_sites_sort ON recommended_sites(enabled,sort_order,id);
CREATE INDEX idx_content_type_section_period ON content_items(lottery_type,section_key,period DESC,sort_order,id);
CREATE INDEX idx_content_type_lookup ON content_items(lottery_type,section_key,period,title,sort_order);
CREATE INDEX idx_text_ads_sort ON text_ads(enabled,sort_order,id);
CREATE INDEX idx_text_ad_domains_sort ON text_ad_domains(enabled,sort_order,id);
